import numpy as np, math
class Driver:
 def __init__(self,s,alpha=1.6):
  self.s=s;self.alpha=alpha;self.pos=s.tip_pose()[0].copy();self.quat=s.tip_down_quat();self.q=s.hold_action().astype(float);self.hist=[]
 def step(self,pos):
  r=self.s.kinematics({'op':'ik','targets':{'tip':np.r_[pos,self.quat].tolist()},'seed':self.q.tolist(),'tol_pos_m':1e-5,'tol_rot_rad':1e-4})
  if not r['ok']:raise RuntimeError(r)
  q=np.array(r['q']);cmd=q+self.alpha*(q-self.q);self.q=q;self.pos=np.array(pos)
  self.s.step(cmd);self.hist.append((self.pos.copy(),self.s.tip_pose()[0].copy()))
 def move(self,pos,speed=.02,settle=0):
  pos=np.array(pos,float);p0=self.pos.copy();n=max(1,int(np.ceil(np.linalg.norm(pos-p0)/speed*20)))
  for i in range(1,n+1):self.step(p0+(pos-p0)*i/n)
  for _ in range(settle):self.step(pos)
 def hold(self,n):
  for _ in range(n):self.step(self.pos)
